using System;
using System.Collections.Generic;
using UnityEngine;
namespace SurvivalLegend.Data { [CreateAssetMenu(fileName="SpecialAugment",menuName="Survival Legend/Special Augment")] public sealed class SpecialAugmentDefinition:ContentDefinition { public string Title,Description,Icon;public float Weight=1;[Tooltip("Leave empty for a common offering.")]public CharacterDefinition Character;public AugmentEffectDefinition[] Effects=Array.Empty<AugmentEffectDefinition>();public AugmentData ToData(){var effects=new AugmentEffectData[Effects==null?0:Effects.Length];for(var i=0;i<effects.Length;i++)effects[i]=Effects[i].ToData();return new AugmentData(Id,Title,Description,Icon,Weight,Character==null?string.Empty:Character.Id,effects);}internal void Validate(IList<CharacterDefinition> characters,IList<SkillDefinition> skills,List<string> errors){if(Character!=null&&!characters.Contains(Character))errors.Add("Special augment '"+Id+"' references an unregistered character.");if(Effects==null||Effects.Length==0)errors.Add("Special augment '"+Id+"' needs at least one effect.");else foreach(var e in Effects){if(e==null){errors.Add("Special augment '"+Id+"' has a missing effect.");continue;}if(e.Skill!=null&&!skills.Contains(e.Skill))errors.Add("Special augment '"+Id+"' references an unregistered skill.");if((e.Kind==AugmentEffectKind.Patch||e.Kind==AugmentEffectKind.Repeat||e.Kind==AugmentEffectKind.AddEffect)&&e.Skill==null)errors.Add("Special augment '"+Id+"' needs a skill for "+e.Kind+".");if(e.Kind==AugmentEffectKind.AddEffect&&e.InjectedEffect==null)errors.Add("Special augment '"+Id+"' needs an injected effect.");}} } }
